import { mkdirSync } from 'node:fs';

// Numbers chosen here:
const CAP_PER_TYPE_PER_DAY = 1; // at most 1 notification of one type per user per recipient-local day
const COOLDOWN_BASE_DAYS = 2; // after a dismissal: 2 days, doubling per further dismissal
const COOLDOWN_MAX_DAYS = 14; // cooldown never exceeds 14 days
const DAY_MS = 86400000;

const PLACEHOLDER_ZONES = new Set(['UTC', 'ETC/UTC', 'GMT', 'ETC/GMT', 'Z']);

function stateDir() {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error('STATE_DIR is not set');
  mkdirSync(dir, { recursive: true });
  return dir;
}

const enc = (s) => encodeURIComponent(String(s)).replace(/%/g, '~');
const kOut = (u, t) => `optout.${enc(u)}.${enc(t)}`;
const kDis = (u, t) => `dismiss.${enc(u)}.${enc(t)}`;
const kId = (id) => `sent.${enc(id)}`;
const kCap = (u, t, day) => `cap.${enc(u)}.${enc(t)}.${enc(day)}`;

function usableZone(z) {
  return typeof z === 'string' && z.trim() !== '' && !PLACEHOLDER_ZONES.has(z.trim().toUpperCase()) && gkZoneOk(z.trim());
}

function pickZone(user) {
  if (usableZone(user?.deviceTimezone)) return user.deviceTimezone.trim();
  if (usableZone(user?.timezone)) return user.timezone.trim();
  return null;
}

const hold = (reason, extra = {}) => ({ send: false, reason, ...extra });

export async function decide({ user, candidate, now, flags } = {}) {
  if (!flags || flags.proactiveEnabled !== true) {
    return hold('Proactive notifications are switched off by operations right now.');
  }
  if (!user?.id || !candidate?.id || !candidate?.type) {
    return hold('The user or notification details are missing, so nothing is sent.');
  }
  const dir = stateDir();
  const ms = now instanceof Date ? now.getTime() : NaN;
  if (!Number.isFinite(ms)) return hold('The current time is unknown, so nothing is sent.');

  // Opt-out beats everything, for every worker.
  if (gkRead(dir, kOut(user.id, candidate.type))) {
    return hold(`The user switched off "${candidate.type}" notifications (opt-out), so nothing is sent.`);
  }

  // Redelivery: the same notification id keeps its answer and spends nothing twice.
  if (gkRead(dir, kId(candidate.id))) return { send: true, reason: null };

  // Consent: absent or false means off.
  if (user.consents?.marketing !== true) {
    return hold('The user has not given marketing consent, so no proactive notification is sent.');
  }

  const zone = pickZone(user);
  if (!zone) {
    return hold('The user\'s time zone is unknown or invalid, so the local day cannot be determined and nothing is sent.');
  }

  // Dismissal cooldown.
  const dis = gkRead(dir, kDis(user.id, candidate.type));
  if (dis && Number.isFinite(dis.until) && ms < dis.until) {
    return hold(`The user dismissed "${candidate.type}" recently; it is paused until ${gkFmt(dis.until, zone)}.`, { nextAllowedAt: dis.until });
  }

  // Claim the id, then spend the daily cap atomically.
  if (!gkClaim(dir, kId(candidate.id))) return { send: true, reason: null };
  const day = gkDayKey(ms, zone);
  const c = gkCount(dir, kCap(user.id, candidate.type, day), CAP_PER_TYPE_PER_DAY);
  if (!c.ok) {
    gkUnclaim(dir, kId(candidate.id));
    const next = gkNextMidnight(ms, zone);
    return hold(`Daily limit reached: only ${CAP_PER_TYPE_PER_DAY} "${candidate.type}" notification per day; next one allowed from ${gkFmt(next, zone)}.`, { nextAllowedAt: next });
  }
  return { send: true, reason: null };
}

export async function recordDismissal(userId, type, now) {
  const dir = stateDir();
  const ms = now instanceof Date ? now.getTime() : Date.now();
  const key = kDis(userId, type);
  // Serialise the read-modify-write across workers with a short claim lock.
  const lock = `lock.${key}`;
  for (let i = 0; i < 200 && !gkClaim(dir, lock); i++) await new Promise((r) => setTimeout(r, 10));
  try {
    const prev = gkRead(dir, key);
    const n = (prev?.n || 0) + 1;
    const days = Math.min(COOLDOWN_BASE_DAYS * 2 ** (n - 1), COOLDOWN_MAX_DAYS);
    gkWrite(dir, key, { n, last: ms, until: ms + days * DAY_MS });
  } finally {
    gkUnclaim(dir, lock);
  }
}

export async function optOut(userId, type) {
  gkWrite(stateDir(), kOut(userId, type), { at: Date.now() });
}
